mapper.select:
select d.status as status, count(*) as cnt from meal_order d where d.del_flag = '0' and d.create_time >= concat(#{startDay}, ' 00:00:00') and d.create_time <= concat(#{endDay}, ' 23:59:59')
and d.dept_id = #{deptId}
group by d.status

select date_format(d.create_time, '%Y-%m-%d') as d_date, count(*) as cnt from meal_order d where d.del_flag = '0' and d.create_time >= concat(#{startDay}, ' 00:00:00') and d.create_time <= concat(#{endDay}, ' 23:59:59')
and d.dept_id = #{deptId}
group by d_date

select i.dish_name as dish_name, sum(i.count) as cnt from meal_order_item i inner join meal_order d on d.order_id = i.order_id where d.del_flag = '0' and d.create_time >= concat(#{startDay}, ' 00:00:00') and d.create_time <= concat(#{endDay}, ' 23:59:59')
and d.dept_id = #{deptId}
group by i.dish_name order by cnt desc limit #{limit}
